package com.example.audit.service; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.example.audit.api.dto.*; import com.example.audit.config.AppProperties; import com.example.audit.domain.AuditEvent; import com.example.audit.repository.AuditEventRepository; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class AuditServiceTest { @Mock AuditEventRepository repo; AuditService service; @BeforeEach void setUp(){service=new AuditService(repo,new HashService(),new AppProperties(new AppProperties.Jwt("12345678901234567890123456789012","x",10),new AppProperties.Audit("GENESIS",365)));} @Test void appendUsesGenesisForFirstRecord(){when(repo.findTopByOrderByChainSequenceDesc()).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));AuditEventResponse r=service.append(new CreateAuditEventRequest("READ","u","ACCOUNT","1","{}"));assertEquals(1,r.chainSequence());assertEquals("GENESIS",r.previousHash());} @Test void emptyChainVerifies(){when(repo.findAllByOrderByChainSequenceAsc()).thenReturn(List.of());assertTrue(service.verify().intact());} }
